import math

N = 2051325

def is_perfect_fourth_power(n):
    if n < 0:
        return False
    if n == 0:
        return True

    # Calculate the fourth root
    # Using integer root finding for precision
    low = 1
    high = int(n**(0.25)) + 2

    root = -1
    while low <= high:
        mid = (low + high) // 2
        mid4 = mid**4
        if mid4 == n:
            return True
        elif mid4 < n:
            root = mid
            low = mid + 1
        else:
            high = mid - 1
    return False

print(f"N = {N}")

# Expanding the search range based on expectation of a structured solution
C_values_to_check = range(2, 51) # Focusing on a bit wider range
solutions = []

for C in C_values_to_check:
    # Calculate C^3 * N - 1
    try:
        target = C**3 * N - 1
    except OverflowError:
        # Should not happen for C up to 50, but good practice
        continue

    if is_perfect_fourth_power(target):
        solutions.append(C)
        print(f"Found solution C = {C}. Target = {target}")

if not solutions:
    print("No solution found in the expanded range C = 2 to 50.")
